"""Semantic version ordering."""


def _ident(part):
    # Numeric identifiers compare numerically and sort before alphanumeric ones.
    return (0, int(part), "") if part.isdigit() else (1, 0, part)


def key(version):
    """Sort key: a pre-release (1.0.0-alpha) sorts before its release (1.0.0)."""
    core, sep, pre = version.partition("-")
    nums = tuple(int(x) for x in core.split("."))
    if not sep:
        # Release: flag 1 sorts after any pre-release flag 0 with the same core.
        return (nums, 1, ())
    return (nums, 0, tuple(_ident(p) for p in pre.split(".")))
