"""Caret ranges like ^1.2.3."""


def _parse(v):
    core = v.split("-", 1)[0]
    nums = tuple(int(x) for x in core.split("."))
    return nums + (0,) * (3 - len(nums))


def satisfies(version, rng):
    """^X.Y.Z allows >= X.Y.Z and below the next bump of the first non-zero part.

    ^1.2.3 -> >=1.2.3 <2.0.0; ^0.2.3 -> >=0.2.3 <0.3.0; ^0.0.3 -> =0.0.3.
    """
    base = _parse(rng.lstrip("^"))
    v = _parse(version)
    if v < base:
        return False
    if base[0] > 0:
        return v[0] == base[0]
    if base[1] > 0:
        return v[:2] == base[:2]
    return v[:3] == base[:3]
